package io.legado.app.lib.epub

import org.w3c.dom.Element
import org.xml.sax.InputSource
import java.io.File
import java.io.IOException
import java.io.StringReader
import java.net.URI
import java.net.URISyntaxException
import java.security.MessageDigest
import java.util.zip.CRC32
import java.util.zip.ZipEntry
import java.util.zip.ZipFile
import java.util.zip.ZipInputStream
import javax.xml.parsers.DocumentBuilderFactory

/** Verifies both the generated bytes and the essential reading order of recovered EPUBs. */
internal object EpubExportIntegrity {
    data class Expected(val spine: List<String>, val contentDigests: Map<String, String>)
    data class Structure(val spine: List<String>, val manifest: Set<String>)

    private const val maxPackageXmlBytes = 32L * 1024 * 1024
    private const val containerNamespace = "urn:oasis:names:tc:opendocument:xmlns:container"
    private const val opfNamespace = "http://www.idpf.org/2007/opf"
    private const val epubNamespace = "http://www.idpf.org/2007/ops"
    private const val xhtmlNamespace = "http://www.w3.org/1999/xhtml"
    private const val xhtmlType = "application/xhtml+xml"
    private val mimetype = "application/epub+zip".toByteArray(Charsets.US_ASCII)

    fun verify(file: File, expected: Expected, check: () -> Unit = {}) {
        check()
        ZipInputStream(file.inputStream().buffered()).use { local ->
            val entry = local.nextEntry ?: throw IOException("Empty EPUB")
            checkMimetype(entry)
            // Read the stored payload as well as the header, including the local CRC.
            requireValid(mimetype.all { local.read() == it.toInt() } && local.read() == -1, "Invalid EPUB mimetype")
        }
        ZipFile(file).use { zip ->
            val entries = zip.entries().toList()
            checkMimetype(entries.firstOrNull() ?: throw IOException("Empty EPUB"))
            val names = entries.map(ZipEntry::getName).toSet()
            requireValid(names.size == entries.size, "Duplicate ZIP entry")
            requireValid(names == expected.contentDigests.keys, "Generated files changed")
            requireValid(zip.getInputStream(entries.first()).use { input ->
                mimetype.all { input.read() == it.toInt() } && input.read() == -1
            }, "Invalid central EPUB mimetype")
            val buffer = ByteArray(64 * 1024)
            for (entry in entries) {
                check()
                requireValid(!entry.isDirectory && validPath(entry.name), "Invalid ZIP path")
                requireValid(
                    entryDigest(zip, entry, buffer, check) == expected.contentDigests.getValue(entry.name),
                    "Content changed: ${entry.name}",
                )
            }
            val structure = readPackage(zip, check)
            requireValid(structure.spine == expected.spine, "Chapter order or count changed")
        }
    }

    private fun checkMimetype(entry: ZipEntry) {
        requireValid(
            entry.name == "mimetype" && entry.method == ZipEntry.STORED &&
                entry.size == mimetype.size.toLong() && entry.extra?.isEmpty() != false,
            "Invalid EPUB mimetype entry",
        )
    }

    internal fun readPackage(zip: ZipFile, check: () -> Unit = {}): Structure {
        val container = readXml(zip, "META-INF/container.xml", check)
        requireValid(container.localName == "container" && container.namespaceURI == containerNamespace, "Invalid EPUB container")
        val root = container.elements(containerNamespace, "rootfile").singleOrNull()
            ?: throw IOException("Missing package document")
        val opf = resolve("", root.getAttribute("full-path"))
        val pkg = readXml(zip, opf, check)
        requireValid(pkg.localName == "package" && pkg.namespaceURI == opfNamespace, "Invalid package document")
        val manifest = pkg.elements(opfNamespace, "manifest").singleOrNull() ?: throw IOException("Missing manifest")
        val spine = pkg.elements(opfNamespace, "spine").singleOrNull() ?: throw IOException("Missing spine")
        val items = manifest.elements(opfNamespace, "item")
        val byId = items.associateBy { it.getAttribute("id") }
        requireValid(items.isNotEmpty() && byId.size == items.size && "" !in byId, "Invalid manifest IDs")
        val paths = byId.mapValues { (_, item) ->
            check()
            resolve(opf, item.getAttribute("href")).also { path ->
                requireValid(zip.getEntry(path)?.isDirectory == false, "Missing manifest resource: $path")
            }
        }
        val resources = paths.values.toSet()
        requireValid(resources.size == items.size, "Duplicate manifest paths")
        val ordered = spine.elements(opfNamespace, "itemref").map { ref ->
            val id = ref.getAttribute("idref")
            requireValid(byId[id]?.getAttribute("media-type") == xhtmlType, "Invalid spine item")
            paths.getValue(id)
        }
        requireValid(ordered.isNotEmpty() && ordered.toSet().size == ordered.size, "Invalid spine order")

        val nav = items.singleOrNull { "nav" in it.getAttribute("properties").split(Regex("\\s+")) }
            ?: throw IOException("Missing or duplicate EPUB navigation")
        requireValid(nav.getAttribute("media-type") == xhtmlType, "Invalid navigation type")
        val navPath = paths.getValue(nav.getAttribute("id"))
        val document = readXml(zip, navPath, check)
        requireValid(document.localName == "html" && document.namespaceURI == xhtmlNamespace, "Invalid EPUB navigation")
        val toc = document.elements(xhtmlNamespace, "nav").singleOrNull {
            "toc" in it.getAttributeNS(epubNamespace, "type").split(Regex("\\s+"))
        } ?: throw IOException("Missing EPUB table of contents")
        val navigation = toc.elements(xhtmlNamespace, "a").map { resolve(navPath, it.getAttribute("href")) }
        requireValid(navigation == ordered, "Navigation omits or reorders spine chapters")
        return Structure(ordered, resources)
    }

    private fun entryDigest(zip: ZipFile, entry: ZipEntry, buffer: ByteArray, check: () -> Unit): String {
        val crc = CRC32()
        val digest = MessageDigest.getInstance("SHA-256")
        var length = 0L
        zip.getInputStream(entry).use { input ->
            while (true) {
                check()
                val n = input.read(buffer)
                if (n < 0) break
                length += n
                requireValid(length <= entry.size, "Unexpected entry length: ${entry.name}")
                crc.update(buffer, 0, n)
                digest.update(buffer, 0, n)
            }
        }
        requireValid(length == entry.size && crc.value == entry.crc, "Invalid ZIP CRC or length: ${entry.name}")
        return digest.digest().toHexString()
    }

    internal fun readXml(zip: ZipFile, path: String, check: () -> Unit = {}): Element {
        check()
        val entry = zip.getEntry(path) ?: throw IOException("Missing XML entry: $path")
        requireValid(entry.size in 1..maxPackageXmlBytes, "XML entry exceeds the export profile")
        val bytes = ByteArray(entry.size.toInt())
        zip.getInputStream(entry).use { input ->
            var offset = 0
            while (offset < bytes.size) {
                check()
                val count = input.read(bytes, offset, minOf(64 * 1024, bytes.size - offset))
                requireValid(count > 0, "Truncated XML entry: $path")
                offset += count
            }
            requireValid(input.read() == -1, "Unexpected XML entry length: $path")
        }
        val xml = bytes.decodeToString(throwOnInvalidSequence = true)
        // The UTF-8 profile excludes DTDs before parsing, even on Android parsers with limited SAX flags.
        requireValid("<!DOCTYPE" !in xml, "DTD is outside the export profile")
        val parser = DocumentBuilderFactory.newInstance().apply {
            isNamespaceAware = true
            isExpandEntityReferences = false
        }.newDocumentBuilder()
        parser.setEntityResolver { _, _ -> throw IOException("External EPUB entities are unsupported") }
        return parser.parse(InputSource(StringReader(xml))).documentElement
    }

    private fun Element.elements(namespace: String, name: String): List<Element> {
        val nodes = getElementsByTagNameNS(namespace, name)
        return List(nodes.length) { nodes.item(it) as Element }
    }

    internal fun resolve(parent: String, reference: String): String {
        val ref = try {
            URI(reference)
        } catch (error: URISyntaxException) {
            throw IOException("Invalid EPUB resource path", error)
        }
        val relative = ref.path ?: throw IOException("Non-local EPUB resource: $reference")
        requireValid(reference.isNotEmpty() && !ref.isAbsolute && ref.rawAuthority == null &&
            ref.rawQuery == null && !relative.startsWith('/'), "Non-local EPUB resource: $reference")
        val directory = parent.substringBeforeLast('/', "")
        val path = when {
            relative.isEmpty() -> parent
            directory.isEmpty() -> relative
            else -> "$directory/$relative"
        }
        requireValid(validPath(path), "Invalid EPUB resource path")
        return path
    }

    private fun validPath(path: String) = '\\' !in path && path.split('/').none { it == "" || it == "." || it == ".." }

    private fun requireValid(condition: Boolean, reason: String) {
        if (!condition) throw IOException(reason)
    }
}
